feature.sample:
acs::mlonnx::COnnxMlRuntime rt;
if (rt.Init().IsOk()) {
    auto h = rt.LoadModel("models/classifier.onnx");
    acs::f32 in[4]  = { 1.0f, 2.0f, 3.0f, 4.0f };
    acs::f32 out[2] = {};
    rt.RunInference(h.Value(), in, 4, out, 2);  // 推論 1 回
    rt.UnloadModel(h.Value());
}
rt.Shutdown();

